UPDATE public.cultural_inspirations SET mode='team' WHERE mode='challenge';
CREATE OR REPLACE FUNCTION trip_private.inspiration_vote_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.choice<>'love' THEN RAISE EXCEPTION 'Only emoji reactions are available'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION trip_private.inspiration_vote_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER inspiration_reactions_only BEFORE INSERT OR UPDATE ON public.inspiration_votes FOR EACH ROW EXECUTE FUNCTION trip_private.inspiration_vote_guard();
CREATE OR REPLACE FUNCTION trip_private.quest_item_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.card_id<>OLD.card_id THEN RAISE EXCEPTION 'Quest ownership cannot change'; END IF; IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.culture_quest_sessions s WHERE s.card_id=OLD.card_id AND s.finished_at IS NOT NULL) AND (NEW.answer IS DISTINCT FROM OLD.answer OR NEW.options IS DISTINCT FROM OLD.options OR NEW.prompt IS DISTINCT FROM OLD.prompt) THEN RAISE EXCEPTION 'Finished questions cannot change'; END IF; IF jsonb_typeof(NEW.options)<>'array' OR jsonb_array_length(NEW.options)<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.options) x WHERE jsonb_typeof(x)<>'string' OR length(x #>> '{}')>150) THEN RAISE EXCEPTION 'Add four short choices'; END IF; IF NEW.round_number=2 AND (NEW.photo_path IS NULL OR NOT EXISTS(SELECT 1 FROM public.cultural_inspirations c WHERE c.id=NEW.card_id AND c.photo_path=NEW.photo_path)) THEN RAISE EXCEPTION 'Picture It uses your uploaded photo'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;